<!-- wp:wdl/lw-qa-1 -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">運動が久しぶりでも大丈夫？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">ご自身の経験や体調を伝え、基礎から参加できるクラスか確認しましょう。この制作例では、初めての方向けのクラスを想定しています。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">何を持っていけばいい？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">動きやすい服装、飲み物、タオルなどが必要か予約先へご確認ください。靴下・着替え・マットの貸し出し条件は、スタジオにより異なります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">体調や身体に気がかりがある場合は？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">痛みや治療中の症状などがある場合は、参加する前に医師などの専門家とスタジオへご相談ください。無理をして参加しないようにしましょう。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">このページから予約できますか？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">こちらは架空のスタジオのデザインサンプルです。所在地・営業日・連絡先・予約先は未設定で、実際の予約受付は行っていません。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
<!-- /wp:wdl/lw-qa-1 -->

